      "future": "gelecek",
      "season": "mevsim",
      "ground": "yer/zemin",
      "cold": "soğuk",
      "hungry": "aç",
      "weak": "zayıf",
      "knock": "kapı çalmak",
      "past": "geçmiş",
      "stomach": "mide",
      "honest": "dürüst",
